/** The realtime topics the blocks broadcast on, with their placeholders filled. @public */
export const topics = {
  messaging: () => "messages",
  notifications: (v: { readonly userId: string }) => `notifications:${String(v.userId)}`,
} as const;

/** The arguments of `reads.billing.overview`. @public */
export type BillingOverviewArgs = { readonly organizationId: string; readonly invoiceLimit?: number };

/** What `reads.billing.overview` returns. @public */
export type BillingOverviewResult = {
  readonly customerId: string | null;
  readonly accountId: string | null;
  readonly seats: number;
  readonly subscription: unknown;
  readonly invoices: readonly unknown[];
  readonly usage: readonly unknown[];
};

/** The arguments of `reads.deals.board`. @public */
export type DealsBoardArgs = { readonly pipelineId: string };

/** What `reads.deals.board` returns. @public */
export type DealsBoardResult = {
  readonly pipelineId: string;
  readonly stages: readonly {
    readonly id: string;
    readonly key: string;
    readonly name: string;
    readonly category: string;
    readonly probability: number | null;
    readonly rottingAfterDays: number | null;
    readonly wipLimit: number | null;
    readonly count: number;
    readonly totals: readonly {
      readonly currency: string;
      readonly amount: string;
      readonly weighted: string;
    }[];
    readonly deals: readonly {
      readonly id: string;
      readonly identifier: string;
      readonly name: string;
      readonly amount: string;
      readonly currency: string;
      readonly ownerId: string | null;
      readonly closeOn: string;
      readonly probability: number | null;
      readonly daysInStage: number;
      readonly rotting: boolean;
      readonly nextStep: string | null;
      readonly nextAt: string | null;
      readonly rank: string;
    }[];
  }[];
  readonly weighted: readonly {
    readonly currency: string;
    readonly amount: string;
  }[];
};

/** The arguments of `reads.organizations.overview`. @public */
